from functools import lru_cache

@lru_cache(None)
def f(x, y, last):
    if x == y:
        return 1
    if x > y:
        return 0
    s = 0
    for c, nx in ((1, x + 1), (2, x + 3), (3, x * 2)):
        if c != last:
            s += f(nx, y, c)
    return s

