from collections import deque
dist = {1: 0}
q = deque([1])
while q:
    x = q.popleft()
    if x == 2025:
        print(dist[x])
        break
    for v in (x + 3, x * 2, x - 1):
        if 0 <= v <= 5000 and v not in dist:
            dist[v] = dist[x] + 1
            q.append(v)
